202	    }
203	
204	    /** Adds the claim with its due-by, fixed now and never moved after; returns its id. */
205	    public long add(String sheet, long person, ClaimInput input, LocalDate dueBy) {
206	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
207	        jdbc.update(con -> {
208	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, corrects, due_by, listed)"
209	                    + " VALUES (?, ?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", new String[] { "id" });
210	            ps.setString(1, sheet);
211	            ps.setLong(2, person);
212	            ps.setBigDecimal(3, input.amount());
213	            ps.setDate(4, Date.valueOf(input.date()));
214	            ps.setString(5, input.note());
215	            ps.setString(6, input.corrects());
216	            ps.setDate(7, Date.valueOf(dueBy));
217	            ps.setString(8, sheet);
218	            return ps;
219	        }, keys);
220	        return keys.getKey().longValue();
221	    }
222	
223	    /** Edits a draft claim: false when it is no longer a draft. */
224	    public boolean update(String sheet, long id, ClaimInput input) {
225	        return jdbc.update(
226	                "UPDATE claim SET amount = ?, claimed_on = ?, note = ?, corrects = ? WHERE sheet = ? AND id = ? AND status = 'DRAFT'",
227	                input.amount(), Date.valueOf(input.date()), input.note(), input.corrects(), sheet, id) == 1;
228	    }
229	
230	    /**
231	     * Moves the claim of the person and status it was read with to another person, unbound from any statement and
232	     * listed as the sheet's newest: false when it no longer has that person or status.
233	     */
234	    public boolean reassign(String sheet, long id, long from, ClaimStatus status, long to) {
235	        return jdbc.update("UPDATE claim SET person = ?, stated = FALSE, stated_due = NULL, listed = " + NEXT_LISTED
236	                + " WHERE sheet = ? AND id = ? AND person = ? AND status = ?", to, sheet, sheet, id, from,
237	                status.name()) == 1;
238	    }
239	
240	    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
241	    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
242	        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
243	                id, from.name()) == 1;
244	    }
245	
246	    /** Fixes the claim's due as it is settled, or leaves none with null. */
247	    public void setSettledDue(String sheet, long id, BigDecimal due) {
248	        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
249	    }
250	
251	    /**
252	     * Re-fixes a SETTLED claim's due (null for none), conditional on the due read, so a concurrent change by another
253	     * user is refused, not overwritten; false when it was not.
254	     */
255	    public boolean resettle(String sheet, long id, BigDecimal was, BigDecimal due) {
256	        return jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ? AND status = ?"
257	                + " AND settled_due IS NOT DISTINCT FROM ?", due, sheet, id, ClaimStatus.SETTLED.name(), was) == 1;
258	    }
259	
260	    /** Binds the claim to a statement's figure (null when its grade had no rate), or unbinds it when not stated. */
261	    public void setStated(String sheet, long id, boolean stated, BigDecimal due) {
262	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet = ? AND id = ?", stated, due, sheet, id);
263	    }
264	
265	    /** Records the user who opened the claim. */
266	    public void setOpenedBy(String sheet, long id, String user) {
267	        jdbc.update("UPDATE claim SET opened_by = ? WHERE sheet = ? AND id = ?", user, sheet, id);
268	    }
269	
270	    /** Sets the claim's number on the sheet, or clears it with null. */
271	    public void setNumber(String sheet, long id, Integer number) {
272	        jdbc.update("UPDATE claim SET number_on_sheet = ? WHERE sheet = ? AND id = ?", number, sheet, id);
273	    }
274	
275	    /** Sets the claim's number within its period. */
276	    public void setPeriodNumber(String sheet, long id, String periodNumber) {
277	        jdbc.update("UPDATE claim SET period_number = ? WHERE sheet = ? AND id = ?", periodNumber, sheet, id);
278	    }
279	
280	    /**
281	     * Takes the next number in the sheet's period of the name ("" for the claims in no period): 1 first, then 2,
282	     * and so on, each period counting on its own. Locked as {@link #nextNumber}.
283	     */
284	    public int nextPeriodNumber(String sheet, String period) {
285	        while (true) {
286	            if (jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet = ? AND period = ?",
287	                    sheet, period) == 1) {
288	                return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet = ? AND period = ?",
289	                        Integer.class, sheet, period);
290	            }
291	            try {
292	                jdbc.update("INSERT INTO claim_period_number (sheet, period, last_number) VALUES (?, ?, 1)", sheet, period);
293	                return 1;
294	            } catch (DuplicateKeyException raced) {
295	                // Another user took the period's first number at the same moment: take the one after it.
296	            }
297	        }
298	    }
299	
300	    /**
301	     * Takes the sheet's next claim number: 1 first, then 2, and so on. The counter row stays locked until the
302	     * transaction ends, so two claims opened at once get different numbers.
303	     */
304	    public int nextNumber(String sheet) {
305	        while (true) {
306	            if (jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet = ?", sheet) == 1) {
307	                return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet = ?", Integer.class,
308	                        sheet);
309	            }
310	            try {
311	                jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 1)", sheet);
312	                return 1;
313	            } catch (DuplicateKeyException raced) {
314	                // Another user took the sheet's first number at the same moment: take the one after it.
315	            }
316	        }
317	    }
318	}
319	package net.officefloor.hq.app.rollup;
320	
321	import java.math.BigDecimal;
322	import java.time.LocalDate;
323	import java.util.LinkedHashMap;
324	import java.util.List;
325	import java.util.Map;
326	import java.util.Objects;
327	import net.officefloor.hq.app.Audit;
328	import net.officefloor.hq.app.claim.Claim;
329	import net.officefloor.hq.app.claim.Claims;
330	import net.officefloor.hq.app.claim.Late;
331	import net.officefloor.hq.app.person.People;
332	import net.officefloor.hq.app.person.Person;
333	import net.officefloor.hq.app.rate.Rate;
334	import net.officefloor.hq.app.rate.Rates;
335	import net.officefloor.hq.app.setting.Dated;
336	import net.officefloor.hq.app.setting.Settings;
337	import net.officefloor.hq.app.sheet.SheetClock;
338	import org.springframework.stereotype.Service;
339	
340	/**
341	 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total, and the sheet's
342	 * claimed-total, due-total and overdue-total. A change takes them before it writes, then {@link #record} audits the ones it moved: a ROLLUP line
343	 * per person whose figures changed (in the order they were added; a new person counts as changed), then a TOTALS
344	 * line when the sheet's totals changed.
345	 */
346	@Service
347	public class Rollup {
348	
349	    /**
350	     * A person's figures: claimed (two decimals), due-total (two decimals, or n/a) and overdue-total (the dues of
351	     * their counted overdue claims, two decimals).
352	     */
353	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
354	    }
355	
356	    /** The sheet's figures at one moment: per person id, in the order they were added, and the totals. */
357	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
358	    }
359	
360	    private final People people;
361	    private final Claims claims;
362	    private final Rates rates;
363	    private final SheetClock clock;
364	    private final Settings settings;
365	    private final Audit audit;
366	
367	    public Rollup(People people, Claims claims, Rates rates, SheetClock clock, Settings settings, Audit audit) {
368	        this.people = people;
369	        this.claims = claims;
370	        this.rates = rates;
371	        this.clock = clock;
372	        this.settings = settings;
373	        this.audit = audit;
374	    }
375	
376	    /** The sheet's figures now. */
377	    public Snapshot take(String sheet) {
378	        LocalDate today = clock.today(sheet);
379	        List<Rate> sheetRates = rates.list(sheet);
380	        Dated floor = settings.floor(sheet);
381	        BigDecimal cap = settings.cap(sheet);
382	        Late late = settings.late(sheet, today);
383	        List<Claim> all = claims.list(sheet);
384	        Map<Long, Figures> figures = new LinkedHashMap<>();
385	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
386	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
387	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
388	        for (Person person : people.list(sheet)) {
389	            List<Claim> mine = all.stream().filter((c) -> c.person() == person.id() && person.counts(c)).toList();
390	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
391	            BigDecimal due = BigDecimal.ZERO.setScale(2);
392	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
393	            for (Claim claim : mine) {
394	                claimed = claimed.add(new BigDecimal(claim.amount()));
395	                BigDecimal d = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
396	                due = d == null ? due : due.add(d);
397	                if (d != null && late.overdue(claim)) {
398	                    overdue = overdue.add(d);
399	                }
400	            }
401	            // n/a when the grade has no rate on the sheet's today, unless a claim has a figure apart from it.
402	            boolean na = Rate.on(sheetRates, person.grade(), today) == null
403	                    && mine.stream().noneMatch((c) -> person.figureApartFrom(c, today, sheetRates, floor));
404	            due = Settings.capped(due, cap);
405	            claimedTotal = claimedTotal.add(claimed);
406	            overdueTotal = overdueTotal.add(overdue);
407	            if (!na) {
408	                dueTotal = dueTotal.add(due);
409	            }
410	            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), na ? "n/a" : due.toPlainString(),
411	                    overdue.toPlainString()));
412	        }
413	        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString(),
414	                overdueTotal.toPlainString());
415	    }
416	
417	    /** Audits the figures the change moved since {@code before}, after the change's own lines. */
418	    public void record(String sheet, String user, Snapshot before) {
419	        Snapshot after = take(sheet);
420	        String prefix = " sheet=" + sheet + " by=" + user + " ";
421	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
422	            Figures now = entry.getValue();
423	            Figures was = before.people().get(entry.getKey());
424	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
425	                    || !was.overdueTotal().equals(now.overdueTotal())) {
426	                audit.record("ROLLUP" + prefix + "person=" + now.name() + " claimed=" + now.claimed() + " due-total="
427	                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
428	            }
429	        }
430	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
431	                || !Objects.equals(before.dueTotal(), after.dueTotal())
432	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
433	            audit.record("TOTALS" + prefix + "claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
434	                    + " overdue-total=" + after.overdueTotal());
435	        }
436	    }
437	}
