454	/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
455	 *  claim's own status buttons and the bulk actions. */
456	@Service
457	public class ClaimStatusChanger {
458	
459	    private final Claims claims;
460	    private final People people;
461	    private final Rates rates;
462	    private final Periods periods;
463	    private final Roles roles;
464	    private final Settings settings;
465	    private final SheetClock clock;
466	    private final Audit audit;
467	    private final Rollup rollup;
468	    private final ClaimLog log;
469	
470	    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
471	            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log) {
472	        this.claims = claims;
473	        this.people = people;
474	        this.rates = rates;
475	        this.periods = periods;
476	        this.roles = roles;
477	        this.settings = settings;
478	        this.clock = clock;
479	        this.audit = audit;
480	        this.rollup = rollup;
481	        this.log = log;
482	    }
483	
484	    /** Applies the change to the claim, writing nothing when it is refused. */
485	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested)
486	            throws InvalidClaimStatusChangeException {
487	        change(sheet, user, claim, requested, null);
488	    }
489	
490	    /** Applies the change to the claim (a reject gives its reason), writing nothing when it is refused. */
491	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
492	            throws InvalidClaimStatusChangeException {
493	        if (periods.closedOn(sheet, LocalDate.parse(claim.date()))) {
494	            throw new InvalidClaimStatusChangeException("A claim dated inside a closed period cannot change status");
495	        }
496	        // Four eyes: the user who opened a claim may not settle it, nor approve it.
497	        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
498	                && user.equals(claim.openedBy())) {
499	            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle or approve it");
500	        }
501	        // Only a steward approves or rejects a PENDING claim; a reject gives a reason.
502	        if ((requested == ClaimStatusChange.APPROVE || requested == ClaimStatusChange.REJECT)
503	                && !Role.STEWARD.equals(roles.of(sheet, user))) {
504	            throw new InvalidClaimStatusChangeException("Only a steward approves or rejects a claim");
505	        }
506	        if (requested == ClaimStatusChange.REJECT && (reason == null || reason.isBlank())) {
507	            throw new InvalidClaimStatusChangeException("A reject needs a reason");
508	        }
509	        Person person = people.find(sheet, claim.person());
510	        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit); above
511	        // it the claim goes to PENDING for a steward to approve. A steward settles anything.
512	        if (requested == ClaimStatusChange.SETTLE && claim.status() == ClaimStatus.OPEN
513	                && Role.CLERK.equals(roles.of(sheet, user))) {
514	            BigDecimal limit = settings.clerkLimit(sheet);
515	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
516	                    settings.late(sheet, clock.today(sheet)));
517	            if (limit != null && due != null && due.compareTo(limit) > 0) {
518	                requested = ClaimStatusChange.PEND;
519	            }
520	        }
521	        Rollup.Snapshot before = rollup.take(sheet);
522	        ClaimStatus next = claim.status().after(requested);
523	        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
524	        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
525	            throw new InvalidClaimStatusChangeException(
526	                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
527	        }
528	        // Opening gives the sheet's next number, or, while the sheet numbers by period from on or before its today,
529	        // the next number in the claim's period (X for none); a voided claim keeps the number it had (never reused).
530	        Claim changed = claim;
531	        if (requested == ClaimStatusChange.OPEN) {
532	            LocalDate from = settings.periodNumberingFrom(sheet);
533	            if (from != null && !clock.today(sheet).isBefore(from)) {
534	                String period = periods.nameOn(sheet, LocalDate.parse(claim.date()));
535	                String key = period == null ? "" : period;
536	                changed = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
537	                claims.setPeriodNumber(sheet, claim.id(), changed.periodNumber());
538	            } else {
539	                changed = claim.withNumber(claims.nextNumber(sheet));
540	                claims.setNumber(sheet, claim.id(), changed.number());
541	            }
542	            claims.setOpenedBy(sheet, claim.id(), user);
543	        }
544	        String fields = changed.statusAuditFields(person.name());
545	        // Settling (or approving a PENDING claim, its live figure then) fixes the due at the person's grade rate in force on the claim's date (or the figure its
546	        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
547	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
548	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
549	                    settings.late(sheet, clock.today(sheet)));
550	            claims.setSettledDue(sheet, claim.id(), due);
551	            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
552	        }
553	        if (requested == ClaimStatusChange.REJECT) {
554	            fields += " reason=" + reason.trim();
555	        }
556	        log.record(sheet, user, claim.id());
557	        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
558	        rollup.record(sheet, user, before);
559	    }
560	}
